WFJ.Data.add("book", {
  ["783a62167b79083f"] = { "Gul'danの裏切りによって常備兵力の半分近くを失い、途方に暮れたDoomhammerは、撤退してAllianceに対する最大の勝機を捨てざるを得なかった。", "." },
  ["784078927445c977"] = { "それどころか、しばしば予想とはまさに正反対の反応を示したのである！ まるでペンダントが意図的に私の実験を台無しにしているかのようであった。\n\nまるで、考え、生きているかのように。\n\n腹は立ったが、くじけはしなかった。私はペンダントを不活性な石の塊とみなす前提をやめ、生き物とみなす前提に切り替えた。\n\nだが、またしても失敗した。", "." },
  ["786aaf2e2b4064ae"] = { "聖なる光が背中を温めてくれて、毎日新しい発見がある。Ironforgeの子として生きるには胸躍る時代だ。Explorer's Leagueは、さらに古い問いへの長く失われた答えを求めて、日々前進している。そして今、troggどもや国境を脅かすあらゆる脅威との戦いを助ける信徒として、お前が加わってくれた。\n\n時間ができたら俺を訪ねてくれ。Anvilmarの奥、丘をちょっと登ったところにいる。\n\n- プリーストのトレーナー、Branstock Khalder", "." },
  ["786baadf32a4c009"] = { "Ranger Captain Alleria Windrunner\n\nQuel'Thalasの名高きトロールハンター。Draenorというオークの故郷へ進軍したAlliance Expeditionの筆頭斥候にして諜報員。死亡したものと推定される。\n\n姉上、あなたの心は風に乗るどの矢よりもまっすぐに飛んだ。あなたは我らがOrderで最も輝ける者であり、一族で最も愛された者であった。\n\n- Sylvanas Windrunner - Quel'Thalasのレンジャー将軍", "." },
  ["787b99cb0be1b70a"] = { "この3つの品、Star、Hand、そしてHeartを持ってくれば、Yagyin's Digestはお前のものだ。\n\n-G.B.", "." },
  ["787f8cee9bbbbd52"] = { "Min'lothは吼え、その魔法は手下たちの呪文の力を集め、彼はそれを迫り来るKrakkenへと放った。\n\n海は割れ、Min'lothの呪文はNeptulonの僕たちへと突き進んだ。稲妻が空を引き裂き、呪文は彼らを打ち、千の雷が落ちて水を沸き立たせ、大地に焼け焦げた穴を穿った。\n\nMin'lothは勝利の叫びを上げた。自らの呪文が巨大な獣たちを倒すと確信して。", "." },
  ["788050816777ea0c"] = { "--3日目--\n\nおお、なんと素晴らしい発見だ！\n\n今日、探索中に大発見をした。猪のような生き物のものらしい、巨大な遺骸だ。その頭蓋骨は私の背丈の何倍もの高さにそびえていた。その獣の歯は一本一本が、どんなものでも小さく見せてしまいそうなほどだ……そう、ドワーフでさえも。発見物のあまりの大きさから、これは噂に聞くOld Godsの1柱の遺骸だと私は考えている。", "." },
  ["7895de6fdb1a9062"] = { "信仰だ。信仰こそが、隷属の喜びが我らに降り注ぐ泉なのだ。信仰は、Silithusの最も寒い夜にも我らを温めてくれる。信仰は、Ending Daysが訪れる時、我らを主たちの恩寵のうちに留めてくれる。\n\n信仰が我らを救うのだ。", "." },
  ["78df567007b1a4ac"] = { "最終的にHellscreamは、Thrallが悪魔の王Mannorothを倒すのを助けることで名誉を取り戻した。Mannorothこそ、最初にオークを憎しみと怒りの血脈で呪った者である。Mannorothの死によって、オークの血の呪いはついに終わりを迎えた。", "." },
  ["78fb356c5c701894"] = { "その剣は確かに彼に計り知れない力を与えたが、同時に彼の魂を奪い、彼をLich Kingの死の騎士の中で最も強大な者へと変えた。魂を捨て去り、正気を打ち砕かれたArthasは、Scourgeを率いて自らの王国に攻め入った。ついにArthasは実の父であるKing Terenasを殺し、Lich Kingの鉄のかかとでLordaeronを踏みにじった。", "." },
})
